import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class BTreeScenario {
    private final int minDegree;
    private final List<Integer> insertedKeys;
    private final List<Integer> expectedKeys;
    private final List<SearchExpectation> searchExpectations;

    private BTreeScenario(int minDegree, List<Integer> insertedKeys, List<SearchExpectation> searchExpectations) {
        this.minDegree = minDegree;
        this.insertedKeys = List.copyOf(insertedKeys);
        this.expectedKeys = sortedCopy(insertedKeys);
        this.searchExpectations = List.copyOf(searchExpectations);
    }

    static BTreeScenario fromKeys(int minDegree, int[] insertedKeys, SearchExpectation... searchExpectations) {
        return new BTreeScenario(minDegree, toList(insertedKeys), List.of(searchExpectations));
    }

    BTree createTree() {
        return BTree.fromKeys(minDegree, insertedKeys);
    }

    int minDegree() {
        return minDegree;
    }

    List<Integer> insertedKeys() {
        return insertedKeys;
    }

    List<Integer> expectedKeys() {
        return expectedKeys;
    }

    List<SearchExpectation> searchExpectations() {
        return searchExpectations;
    }

    static SearchExpectation present(int key) {
        return new SearchExpectation(key, true);
    }

    static SearchExpectation missing(int key) {
        return new SearchExpectation(key, false);
    }

    private static List<Integer> sortedCopy(List<Integer> values) {
        List<Integer> sorted = new ArrayList<>(values);
        Collections.sort(sorted);
        return sorted;
    }

    private static List<Integer> toList(int[] values) {
        List<Integer> result = new ArrayList<>(values.length);
        for (int value : values) {
            result.add(value);
        }
        return result;
    }

    static final class SearchExpectation {
        private final int key;
        private final boolean present;

        private SearchExpectation(int key, boolean present) {
            this.key = key;
            this.present = present;
        }

        int key() {
            return key;
        }

        boolean isPresent() {
            return present;
        }
    }
}

import java.util.List;

final class BTreeTestSupport {
    private BTreeTestSupport() {
    }

    static void runTest(String name, Runnable test) {
        try {
            test.run();
        } catch (Throwable throwable) {
            throw new AssertionError("Test failed: " + name, throwable);
        }
    }

    static void expectThrows(Class<? extends Throwable> expectedType, ThrowingRunnable action, String message) {
        try {
            action.run();
        } catch (Throwable throwable) {
            if (expectedType.isInstance(throwable)) {
                return;
            }
            throw new AssertionError(message + " Expected exception type: " + expectedType.getSimpleName()
                    + ", Actual: " + throwable.getClass().getSimpleName(), throwable);
        }

        throw new AssertionError(message);
    }

    static void assertTreeContents(BTree tree, List<Integer> expectedKeys) {
        assertEquals(expectedKeys, tree.toList(), "Unexpected in-order traversal.");
        assertEquals(formatKeys(expectedKeys), tree.toString(), "Unexpected string representation.");
        assertEquals(expectedKeys.isEmpty(), tree.isEmpty(), "Unexpected empty-state result.");
    }

    static void assertMatchesScenario(BTreeScenario scenario) {
        BTree tree = scenario.createTree();
        assertTreeContents(tree, scenario.expectedKeys());

        for (BTreeScenario.SearchExpectation expectation : scenario.searchExpectations()) {
            assertSearchExpectation(tree, expectation);
        }
    }

    static void assertContains(BTree tree, int key) {
        assertTrue(tree.contains(key), "Expected inserted key to be found: " + key);
    }

    static void assertDoesNotContain(BTree tree, int key) {
        assertFalse(tree.contains(key), "Expected missing key to be absent: " + key);
    }

    static void assertSearchExpectation(BTree tree, BTreeScenario.SearchExpectation expectation) {
        if (expectation.isPresent()) {
            assertContains(tree, expectation.key());
            return;
        }

        assertDoesNotContain(tree, expectation.key());
    }

    private static String formatKeys(List<Integer> keys) {
        StringBuilder builder = new StringBuilder();
        for (int key : keys) {
            if (builder.length() > 0) {
                builder.append(' ');
            }
            builder.append(key);
        }
        return builder.toString();
    }

    private static void assertEquals(Object expected, Object actual, String message) {
        if (!expected.equals(actual)) {
            throw new AssertionError(message + " Expected: " + expected + ", Actual: " + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    private static void assertFalse(boolean condition, String message) {
        assertTrue(!condition, message);
    }

    @FunctionalInterface
    interface ThrowingRunnable {
        void run() throws Throwable;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.StringJoiner;
import java.util.function.IntConsumer;

public final class BTree {
    private final int minDegree;
    private Node root;

    public static BTree fromKeys(int minDegree, int... keys) {
        BTree tree = new BTree(minDegree);
        tree.insertAll(keys);
        return tree;
    }

    public static BTree fromKeys(int minDegree, Iterable<Integer> keys) {
        BTree tree = new BTree(minDegree);
        tree.insertAll(keys);
        return tree;
    }

    public BTree(int minDegree) {
        validateMinDegree(minDegree);
        this.minDegree = minDegree;
    }

    public void insert(int key) {
        if (root == null) {
            root = createLeafNode(key);
            return;
        }

        splitRootIfNeeded();
        root.insertNonFull(key);
    }

    public void insertAll(int... keys) {
        Objects.requireNonNull(keys, "keys");
        for (int key : keys) {
            insert(key);
        }
    }

    public void insertAll(Iterable<Integer> keys) {
        Objects.requireNonNull(keys, "keys");
        for (int key : keys) {
            insert(key);
        }
    }

    public boolean contains(int key) {
        return root != null && root.contains(key);
    }

    public boolean isEmpty() {
        return root == null;
    }

    public void forEachKey(IntConsumer action) {
        Objects.requireNonNull(action, "action");
        if (root != null) {
            root.forEachKey(action);
        }
    }

    public List<Integer> toList() {
        List<Integer> orderedKeys = new ArrayList<>();
        forEachKey(orderedKeys::add);
        return orderedKeys;
    }

    private void splitRootIfNeeded() {
        if (!root.isFull()) {
            return;
        }

        Node newRoot = createInternalNode();
        newRoot.setChild(0, root);
        newRoot.splitChild(0);
        root = newRoot;
    }

    private static void validateMinDegree(int minDegree) {
        if (minDegree < 2) {
            throw new IllegalArgumentException("B-tree minimum degree must be at least 2.");
        }
    }

    @Override
    public String toString() {
        StringJoiner joiner = new StringJoiner(" ");
        forEachKey(key -> joiner.add(Integer.toString(key)));
        return joiner.toString();
    }

    private Node createLeafNode(int firstKey) {
        Node node = new Node(true);
        node.keys[0] = firstKey;
        node.keyCount = 1;
        return node;
    }

    private Node createInternalNode() {
        return new Node(false);
    }

    private int maxKeysPerNode() {
        return 2 * minDegree - 1;
    }

    private int maxChildrenPerNode() {
        return 2 * minDegree;
    }

    private int medianKeyIndex() {
        return minDegree - 1;
    }

    private final class Node {
        private final int[] keys;
        private final Node[] children;
        private final boolean leaf;
        private int keyCount;

        private Node(boolean leaf) {
            this.leaf = leaf;
            this.keys = new int[maxKeysPerNode()];
            this.children = new Node[maxChildrenPerNode()];
        }

        private boolean isFull() {
            return keyCount == keys.length;
        }

        private void setChild(int index, Node child) {
            children[index] = child;
        }

        private boolean contains(int targetKey) {
            int index = findFirstGreaterOrEqualIndex(targetKey);
            if (matchesKeyAt(index, targetKey)) {
                return true;
            }

            return !leaf && children[index].contains(targetKey);
        }

        private void forEachKey(IntConsumer action) {
            for (int i = 0; i < keyCount; i++) {
                if (!leaf) {
                    children[i].forEachKey(action);
                }
                action.accept(keys[i]);
            }

            if (!leaf) {
                children[keyCount].forEachKey(action);
            }
        }

        private void insertNonFull(int key) {
            if (leaf) {
                insertIntoLeaf(key);
                return;
            }

            int childIndex = findFirstGreaterOrEqualIndex(key);
            childIndex = prepareChildForInsert(childIndex, key);
            children[childIndex].insertNonFull(key);
        }

        private void insertIntoLeaf(int key) {
            int insertAt = findFirstGreaterOrEqualIndex(key);
            shiftKeysRightFrom(insertAt);
            keys[insertAt] = key;
            keyCount++;
        }

        private int prepareChildForInsert(int childIndex, int key) {
            if (!children[childIndex].isFull()) {
                return childIndex;
            }

            splitChild(childIndex);
            if (key > keys[childIndex]) {
                return childIndex + 1;
            }
            return childIndex;
        }

        private void splitChild(int childIndex) {
            Node child = children[childIndex];
            Node sibling = new Node(child.leaf);
            int medianKey = child.keys[medianKeyIndex()];

            sibling.keyCount = minDegree - 1;
            copyUpperHalfOfKeysToSibling(child, sibling);
            if (!child.leaf) {
                copyUpperHalfOfChildrenToSibling(child, sibling);
            }

            child.keyCount = minDegree - 1;
            shiftChildrenRightFrom(childIndex + 1);
            children[childIndex + 1] = sibling;

            shiftKeysRightFrom(childIndex);
            keys[childIndex] = medianKey;
            keyCount++;
        }

        private void copyUpperHalfOfKeysToSibling(Node source, Node sibling) {
            System.arraycopy(source.keys, minDegree, sibling.keys, 0, minDegree - 1);
        }

        private void copyUpperHalfOfChildrenToSibling(Node source, Node sibling) {
            System.arraycopy(source.children, minDegree, sibling.children, 0, minDegree);
        }

        private void shiftChildrenRightFrom(int fromIndex) {
            int length = keyCount - fromIndex + 1;
            System.arraycopy(children, fromIndex, children, fromIndex + 1, length);
        }

        private void shiftKeysRightFrom(int fromIndex) {
            int length = keyCount - fromIndex;
            System.arraycopy(keys, fromIndex, keys, fromIndex + 1, length);
        }

        private int findFirstGreaterOrEqualIndex(int targetKey) {
            int index = 0;
            while (index < keyCount && targetKey > keys[index]) {
                index++;
            }
            return index;
        }

        private boolean matchesKeyAt(int index, int targetKey) {
            return index < keyCount && keys[index] == targetKey;
        }
    }
}

public final class Main {
    public static void main(String[] args) {
        BTreeScenario scenario = BTreeSamples.defaultScenario();
        BTree tree = scenario.createTree();

        System.out.println("Traversal of the constructed tree is " + tree);

        printSearchResults(tree, scenario.searchExpectations());
    }

    private static void printSearchResults(BTree tree, Iterable<BTreeScenario.SearchExpectation> expectations) {
        for (BTreeScenario.SearchExpectation expectation : expectations) {
            if (tree.contains(expectation.key())) {
                System.out.println(" | Present");
            } else {
                System.out.println(" | Not Present");
            }
        }
    }
}

